const char *nwii_hid_get_device_name(void)
{
    return _nwii_hid_name;
}

void nwii_hid_get_report_descriptor(const uint8_t **descriptor, uint16_t *len)
{
    if (descriptor) *descriptor = _nwii_hid_report_descriptor;
    if (len) *len = (uint16_t)sizeof(_nwii_hid_report_descriptor);
}

void nwii_hid_get_sdp_record(const uint8_t **record, uint16_t *len)
{
    if (record) *record = _nwii_hid_sdp_record;
    if (len) *len = (uint16_t)sizeof(_nwii_hid_sdp_record);
}

void nwii_hid_make_pin(const uint8_t host_addr[6], uint8_t pin_out[NWII_HID_PIN_LEN])
{
    if (host_addr == NULL || pin_out == NULL)
    {
        return;
    }

    for (uint8_t i = 0; i < NWII_HID_PIN_LEN; i++)
    {
        pin_out[i] = host_addr[NWII_HID_PIN_LEN - 1u - i];
    }
}
